class Link:
    """
    A cross-trace link from one span to a span in another trace.

    Links allow recording relationships between spans that live in different traces,
    e.g. connecting a span to a related span in a separate trace.

    Args:
        trace_id: The ID of the target trace the linked span belongs to.
        span_id: The ID of the target span within the target trace.
        attributes: Optional dictionary of metadata attributes associated with the link.
    """

    def __init__(self, trace_id: str, span_id: str, attributes: Optional[dict] = None):
        self.trace_id = trace_id
        self.span_id = span_id
        self.attributes = attributes

    def to_dict(self) -> dict:
        return {
            "trace_id": self.trace_id,
            "span_id": self.span_id,
            "attributes": self.attributes,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Link":
        return cls(
            trace_id=data["trace_id"],
            span_id=data["span_id"],
            attributes=data.get("attributes"),
        )

    def __repr__(self) -> str:
        return (
            f"Link(trace_id={self.trace_id!r}, span_id={self.span_id!r}, "
            f"attributes={self.attributes!r})"
        )

    def __eq__(self, other) -> bool:
        if not isinstance(other, Link):
            return NotImplemented
        return (
            self.trace_id == other.trace_id
            and self.span_id == other.span_id
            and self.attributes == other.attributes
        )
